const !campoPrimario!Seleccionado = watch('!moduloDestino!.0.!campoPrimario!');

const cargar!CampoSecundarioPlural! = useCallback(async (!campoPrimario!) => {
  if (!!campoPrimario!) {
    set!CampoSecundarioPlural!([]);
    return;
  }
  try {
    const result = await recuperar!CampoSecundarioPlural!({ !campoPrimario! }).unwrap();
    const !campoSecundarioPlural!Unicos = [...new Set(
      result
        .filter(item => item.!campoSecundario!)
        .map(item => item.!campoSecundario!.toString().trim()).sort()
    )];

    set!CampoSecundarioPlural!(!campoSecundarioPlural!Unicos);
  } catch (error) {
    console.error('Error al cargar !campoSecundarioPlural!:', error);
    set!CampoSecundarioPlural!([]);
  }
}, [recuperar!CampoSecundarioPlural!]);

useEffect(() => {
  console.log('!campoPrimario!->Seleccionado: ', !campoPrimario!Seleccionado)
  cargar!CampoSecundarioPlural!(!campoPrimario!Seleccionado);
}, [!campoPrimario!Seleccionado, cargar!CampoSecundarioPlural!]);
